package pe.siniestrofacil.application;
import org.junit.jupiter.api.Test; import pe.siniestrofacil.application.dto.CrearSiniestroRequest; import pe.siniestrofacil.application.service.SiniestroService; import pe.siniestrofacil.domain.model.Siniestro; import pe.siniestrofacil.domain.port.SiniestroRepository; import java.time.OffsetDateTime; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
class SiniestroServiceTest { @Test void creaConEstadoReportado(){SiniestroRepository repo=mock(SiniestroRepository.class); SiniestroService service=new SiniestroService(repo); var req=new CrearSiniestroRequest(new CrearSiniestroRequest.PolizaRequest("POL-1"),new CrearSiniestroRequest.VehiculoRequest("ABC-123"),OffsetDateTime.parse("2026-08-20T10:00:00-05:00"),"Piura","COLISION","Daño frontal",new CrearSiniestroRequest.ParticipanteRequest("P1","999","REPORTANTE")); var expected=new Siniestro(10L,1L,2L,req.fecha(),req.ubicacionAproximada(),req.tipoEvento(),req.danosAparentes(),"REPORTADO"); when(repo.createByBusinessKeys(eq("POL-1"),eq("ABC-123"),any(),eq(req.reportante()))).thenReturn(expected); var result=service.create(req); assertEquals(10L,result.id()); assertEquals("REPORTADO",result.estado()); verify(repo).createByBusinessKeys(eq("POL-1"),eq("ABC-123"),any(),eq(req.reportante())); } }